package tri_lion.health.service.health;
import java.io.IOException;import java.time.LocalDate;import java.util.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import tri_lion.health.domain.health.HealthDocument;import tri_lion.health.exception.ApiException;import tri_lion.health.external.storage.ObjectStorage;import tri_lion.health.repository.health.HealthRepositories;import tri_lion.health.security.AuthenticatedUser;
@Service public class HealthDocumentService {private final HealthRepositories.Documents docs;private final ObjectStorage storage;private final AuthenticatedUser auth;public HealthDocumentService(HealthRepositories.Documents d,ObjectStorage s,AuthenticatedUser a){docs=d;storage=s;auth=a;}@Transactional public HealthDocument upload(MultipartFile f,String type,LocalDate measured){Long uid=auth.sensitive().getId();if(f.isEmpty()||f.getSize()>10*1024*1024)throw new ApiException(HttpStatus.PAYLOAD_TOO_LARGE,"파일은 10MB 이하만 업로드할 수 있습니다.");String content=Optional.ofNullable(f.getContentType()).orElse("").toLowerCase();String name=Optional.ofNullable(f.getOriginalFilename()).orElse("file");byte[] b;try{b=f.getBytes();}catch(IOException e){throw new ApiException(HttpStatus.BAD_REQUEST,"파일을 읽을 수 없습니다.");}if(!valid(content,name,b))throw new ApiException(HttpStatus.BAD_REQUEST,"JPG, PNG 또는 PDF 파일만 업로드할 수 있습니다.");String key="health/"+uid+"/"+UUID.randomUUID();storage.put(key,b,content);return docs.save(new HealthDocument(uid,HealthDocument.Type.valueOf(type),key,name,content,b.length,measured));}public Page<HealthDocument> list(int page,int size){return docs.findByUserIdAndDeletedAtIsNullOrderByCreatedAtDesc(auth.sensitive().getId(),PageRequest.of(page,Math.min(size,100)));}@Transactional public void delete(Long id){HealthDocument d=docs.findByIdAndUserIdAndDeletedAtIsNull(id,auth.sensitive().getId()).orElseThrow(()->ApiException.notFound("건강 문서를 찾을 수 없습니다."));storage.delete(d.getObjectKey());d.delete();}private boolean valid(String c,String n,byte[] b){if(b.length<4)return false;boolean jpg=(b[0]&255)==0xff&&(b[1]&255)==0xd8;boolean png=(b[0]&255)==0x89&&b[1]==0x50&&b[2]==0x4e&&b[3]==0x47;boolean pdf=b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F';String l=n.toLowerCase();return(jpg&&List.of("image/jpeg","image/jpg").contains(c)&&(l.endsWith(".jpg")||l.endsWith(".jpeg")))||(png&&c.equals("image/png")&&l.endsWith(".png"))||(pdf&&c.equals("application/pdf")&&l.endsWith(".pdf"));}}
